use std::borrow::Cow;
use std::env;
use std::fmt;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::process;

use clap::{value_parser, Arg, ArgAction, ArgMatches, Command};
use regex::bytes::{NoExpand, Regex, RegexBuilder};

fn main() {
    let bin_name = current_bin_name();
    let mut command = build_command(bin_name);
    let matches = command
        .try_get_matches_from_mut(env::args_os())
        .unwrap_or_else(|err| err.exit());

    if let Err(err) = run(&matches) {
        eprintln!("error: {err}");
        process::exit(1);
    }
}

fn current_bin_name() -> String {
    env::args_os()
        .next()
        .and_then(|arg| Path::new(&arg).file_name().map(|name| name.to_owned()))
        .and_then(|name| name.into_string().ok())
        .unwrap_or_else(|| "sd".to_owned())
}

fn build_command(bin_name: String) -> Command {
    Command::new("sd")
        .bin_name(bin_name)
        .version("1.0.0")
        .about("An intuitive find & replace CLI")
        .term_width(100)
        .arg(
            Arg::new("preview")
                .short('p')
                .long("preview")
                .action(ArgAction::SetTrue)
                .help(
                    "Display changes in a human reviewable format (the specifics of the format are likely to change in the future)",
                ),
        )
        .arg(
            Arg::new("fixed_strings")
                .short('F')
                .long("fixed-strings")
                .action(ArgAction::SetTrue)
                .help("Treat FIND and REPLACE_WITH args as literal strings"),
        )
        .arg(
            Arg::new("max_replacements")
                .short('n')
                .long("max-replacements")
                .value_name("LIMIT")
                .value_parser(value_parser!(usize))
                .default_value("0")
                .help("Limit the number of replacements that can occur per file. 0 indicates unlimited replacements"),
        )
        .arg(
            Arg::new("flags")
                .short('f')
                .long("flags")
                .value_name("FLAGS")
                .help("Regex flags. May be combined (like `-f mc`).")
                .long_help(
                    "Regex flags. May be combined (like `-f mc`).\n\nc - case-sensitive\n\ne - disable multi-line matching\n\ni - case-insensitive\n\nm - multi-line matching\n\ns - make `.` match newlines\n\nw - match full words only",
                ),
        )
        .arg(
            Arg::new("find")
                .value_name("FIND")
                .required(true)
                .help("The regexp or string (if using `-F`) to search for"),
        )
        .arg(
            Arg::new("replace_with")
                .value_name("REPLACE_WITH")
                .required(true)
                .help(
                    "What to replace each match with. Unless in string mode, you may use captured values like $1, $2, etc",
                ),
        )
        .arg(
            Arg::new("files")
                .value_name("FILES")
                .value_parser(value_parser!(PathBuf))
                .num_args(0..)
                .help("The path to file(s). This is optional - sd can also read from STDIN")
                .long_help(
                    "The path to file(s). This is optional - sd can also read from STDIN.\n\nNote: sd modifies files in-place by default. See documentation for examples.",
                ),
        )
}

fn run(matches: &ArgMatches) -> Result<(), AppError> {
    let preview = matches.get_flag("preview");
    let fixed_strings = matches.get_flag("fixed_strings");
    let max_replacements = *matches
        .get_one::<usize>("max_replacements")
        .expect("defaulted by clap");
    let flags = matches
        .get_one::<String>("flags")
        .map(String::as_str)
        .unwrap_or("");
    let find = matches
        .get_one::<String>("find")
        .expect("required by clap");
    let replace_with = matches
        .get_one::<String>("replace_with")
        .expect("required by clap");

    let regex = build_regex(find, fixed_strings, flags).map_err(AppError::InvalidRegex)?;
    let files: Vec<PathBuf> = matches
        .get_many::<PathBuf>("files")
        .map(|paths| paths.cloned().collect())
        .unwrap_or_default();

    if files.is_empty() {
        let mut input = Vec::new();
        io::stdin().read_to_end(&mut input).map_err(AppError::Io)?;
        let output = replace_contents(&regex, &input, replace_with, fixed_strings, max_replacements);
        io::stdout()
            .write_all(output.as_ref())
            .map_err(AppError::Io)?;
        return Ok(());
    }

    for path in &files {
        if !path.exists() {
            return Err(AppError::InvalidPath(path.display().to_string()));
        }
    }

    let mut stdout = io::stdout();
    let multiple_files = files.len() > 1;

    for path in &files {
        let input = fs::read(path).map_err(AppError::Io)?;
        let output = replace_contents(&regex, &input, replace_with, fixed_strings, max_replacements);

        if preview {
            if multiple_files {
                write!(stdout, "----- FILE {} -----\n", path.display()).map_err(AppError::Io)?;
            }
            stdout.write_all(output.as_ref()).map_err(AppError::Io)?;
        } else if output.as_ref() != input.as_slice() {
            fs::write(path, output.as_ref()).map_err(AppError::Io)?;
        }
    }

    Ok(())
}

fn build_regex(find: &str, fixed_strings: bool, flags: &str) -> Result<Regex, regex::Error> {
    let mut pattern = if fixed_strings {
        regex::escape(find)
    } else {
        find.to_owned()
    };

    let mut case_insensitive = false;
    let mut multi_line = true;
    let mut dot_matches_new_line = false;
    let mut match_full_words = false;

    for flag in flags.chars() {
        match flag {
            'c' => case_insensitive = false,
            'e' => multi_line = false,
            'i' => case_insensitive = true,
            'm' => multi_line = true,
            's' => dot_matches_new_line = true,
            'w' => match_full_words = true,
            _ => {}
        }
    }

    if match_full_words {
        pattern = format!(r"\b(?:{pattern})\b");
    }

    let mut builder = RegexBuilder::new(&pattern);
    builder
        .case_insensitive(case_insensitive)
        .multi_line(multi_line)
        .dot_matches_new_line(dot_matches_new_line)
        .unicode(true);
    builder.build()
}

fn replace_contents<'a>(
    regex: &Regex,
    input: &'a [u8],
    replace_with: &str,
    fixed_strings: bool,
    max_replacements: usize,
) -> Cow<'a, [u8]> {
    match (fixed_strings, max_replacements) {
        (true, 0) => regex.replace_all(input, NoExpand(replace_with.as_bytes())),
        (true, limit) => regex.replacen(input, limit, NoExpand(replace_with.as_bytes())),
        (false, 0) => regex.replace_all(input, replace_with.as_bytes()),
        (false, limit) => regex.replacen(input, limit, replace_with.as_bytes()),
    }
}

#[derive(Debug)]
enum AppError {
    InvalidPath(String),
    InvalidRegex(regex::Error),
    Io(io::Error),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidPath(path) => write!(f, "invalid path: {path}"),
            Self::InvalidRegex(err) => write!(f, "invalid regex {err}"),
            Self::Io(err) => err.fmt(f),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{build_regex, replace_contents};

    #[test]
    fn fixed_string_replacements_are_literal() {
        let regex = build_regex("a+b", true, "").unwrap();
        let output = replace_contents(&regex, b"a+b\n", "[$1]", true, 0);
        assert_eq!(output.as_ref(), b"[$1]\n");
    }

    #[test]
    fn flags_are_processed_left_to_right() {
        let regex = build_regex("a", false, "ic").unwrap();
        let output = replace_contents(&regex, b"A\na\n", "X", false, 0);
        assert_eq!(output.as_ref(), b"A\nX\n");
    }

    #[test]
    fn multi_line_is_enabled_by_default() {
        let regex = build_regex("^line", false, "").unwrap();
        let output = replace_contents(&regex, b"line1\nline2\n", "row-", false, 0);
        assert_eq!(output.as_ref(), b"row-1\nrow-2\n");
    }
}

